function openLoadout(){if(salvageMode){selectedWeapons=campaign.frame().weaponSlots.filter(Boolean).map(w=>w.type);if(!selectedWeapons.length){baseUI.show();return;}loadoutConfirmed=false;baseUI.showBrief(selectedWeapons.map(w=>weapons[w].name),async mission=>{selectedMission=sortieMission(mission);await sortieWorld.ready;loadoutConfirmed=true;await start();});return;}makeWeaponImages();renderLoadout();$('overlay').style.display='none';$('loadoutOverlay').hidden=false;$('loadout-rapid').focus?.();}

