function syncAmmo(){if(weapon!=='pistol'&&equippedSlot>0&&selectedWeapons[equippedSlot-1]===weapon)slotAmmo[equippedSlot-1]=Math.max(0,ammo);}
function equipSlot(slot){if(salvageMode&&sortie&&slot===0)return;if(slot>0&&!selectedWeapons[slot-1])return;if(knifeAction){knifeAction=null;dashTime=0;player.vel.x=player.vel.z=0;}knifePoseTime=0;knifeComboWindow=0;knifeQueued=false;knifeBlockTime=0;cancelWeaponChannel();stopMinigun();syncAmmo();equippedSlot=slot;weapon=slot===0?'pistol':selectedWeapons[slot-1];ammo=slot===0||weapon==='pistol'?Infinity:slotAmmo[slot-1];if(salvageMode&&sortie){const item=sortie.weaponItems[slot-1];progression.player.damage=sortie.stats.damage*(1+.1*((item?.level||1)-1))*(SALVAGE.weaponPerk(item).damage||1);}chargeHeld=false;photonCharge=0;lockTarget=null;lockTime=0;firing=false;rightDrag=false;adsBlend=0;recoil=0;shotgunKick=0;$('scope').style.opacity=0;$('rocketLock').style.opacity=0;updateCombatRing();updateSlotHUD();}
function updateSlotHUD(){syncAmmo();const html=selectedWeapons.map((type,i)=>{const amount=type==='pistol'?Infinity:slotAmmo[i]||0,max=type==='pistol'?Infinity:weapons[type].ammo,ratio=type==='pistol'?1:Math.max(0,Math.min(1,amount/max));return `<span style="color:#${slotColors[i].toString(16)}" class="${equippedSlot===i+1?'equipped':''} ${amount===0?'empty':''}"><svg class="slotBar" viewBox="0 0 130 240" aria-hidden="true"><path class="slotTrack" d="${i===0?'M4 12 A108 108 0 0 1 4 228':'M4 22 A98 98 0 0 1 4 218'}"/><path class="slotFill" pathLength="100" style="stroke-dashoffset:${(1-ratio)*100}" d="${i===0?'M4 12 A108 108 0 0 1 4 228':'M4 22 A98 98 0 0 1 4 218'}"/></svg><div class="slotValue"><b>${i+(salvageMode?1:2)} · ${weapons[type].name}</b><strong>${type==='pistol'?'∞':amount+' / '+max}</strong></div></span>`;}).join('');if($('weaponSlots').innerHTML!==html)$('weaponSlots').innerHTML=html;}

const pickupMessages=[];let pickupFlashTime=0;
function supplyFeedback(d,amount,label){const hex=d.kind==='battery'?0x42cfff:d.kind==='equipment'?0x65e5bc:d.kind==='part'?0xc090ff:d.kind==='weapon'?0xffae72:d.kind==='health'?0x83ff94:slotColors[d.slot]??0xffd66b,color='#'+hex.toString(16).padStart(6,'0'),el=document.createElement('div');el.className='pickupMessage';el.style.color=color;const icon={battery:'⚡',part:'▣',equipment:'◈',weapon:'◆',health:'+'}[d.kind]||'▥';el.textContent=`${icon} ${label||(d.kind==='health'?`HP +${amount}`:`${weapons[selectedWeapons[d.slot]]?.name||'탄약'} 탄약 +${amount}`)}`;$('pickupNumbers').appendChild?.(el);pickupMessages.push({el,life:1.5});pickupFlashTime=.35;$('pickupFlash').style.background=`radial-gradient(ellipse at center,transparent 38%,${color}66 100%)`;playSound('ammo-pickup',.5,d.kind==='battery'?1.3:d.kind==='part'?.9:1);if(d.m)burst(d.m.position,hex,24);}
function updateSupplyFeedback(dt){pickupFlashTime=Math.max(0,pickupFlashTime-dt);$('pickupFlash').style.opacity=pickupFlashTime/.35;for(let i=pickupMessages.length-1;i>=0;i--){pickupMessages[i].life-=dt;if(pickupMessages[i].life<=0){pickupMessages[i].el.remove();pickupMessages.splice(i,1);}}}
function collectNearbySupplies(path=[player.pos]){
 for(const d of drops){if(d.life<=0)continue;let near=false;
  for(let i=0;i<path.length;i++){const start=path[Math.max(0,i-1)].clone().add(new THREE.Vector3(0,-.85,0)),end=path[i].clone().add(new THREE.Vector3(0,-.85,0)),delta=end.clone().sub(start),length=delta.lengthSq(),t=length?THREE.MathUtils.clamp(d.m.position.clone().sub(start).dot(delta)/length,0,1):0;
   if(start.addScaledVector(delta,t).distanceToSquared(d.m.position)<2.5**2){near=true;break;}}
  if(near&&pickupSupply(d))d.life=0;
 }
}
function pickupSupply(d){if(salvageMode&&sortie){if(d.kind==='battery'){const gained=Math.min(SALVAGE.SALVAGE_DROPS.batteryCharge,sortie.stats.battery-sortie.battery);sortie.battery=Math.min(sortie.stats.battery,sortie.battery+SALVAGE.SALVAGE_DROPS.batteryCharge);sortie.energyRecovered=(sortie.energyRecovered||0)+gained;supplyFeedback(d,gained,`배터리 +${Math.round(gained)}`);notify(`회수 · 배터리 +${Math.round(gained)}`);return true;}if(d.kind==='part'){const type=d.partType||SALVAGE.lootPart();sortie.cargo.push(SALVAGE.makePart(type,`${Date.now()}-${Math.random().toString(36).slice(2)}`));supplyFeedback(d,1,type==='core'?'핵심 발전 코어 획득':SALVAGE.PARTS[type].name+' 획득');notify(type==='core'?'핵심 발전 코어 회수 · 출발 지점으로 귀환하세요':SALVAGE.PARTS[type].name+' 적재 · 귀환 후 장착 가능');return true;}if(d.kind==='equipment'){const item=SALVAGE.makeEquipment(d.equipmentType);sortie.lootEquipment.push(item);supplyFeedback(d,1,`${SALVAGE.EQUIPMENT[item.type].name} 획득`);notify('장비 회수 · 귀환 후 장착 가능');return true;}if(d.kind==='weapon'){sortie.lootWeapons.push(SALVAGE.makeWeapon(d.weaponType));supplyFeedback(d,1,`${weapons[d.weaponType].name} 획득`);notify(`${weapons[d.weaponType].name} 회수 · 귀환 후 창고 보관`);return true;}if(d.kind==='health')return false;}if(d.kind==='health'){if(player.hp>=maxPlayerHP())return false;const healed=Math.min(30,maxPlayerHP()-player.hp);player.hp+=healed;supplyFeedback(d,healed);notify('HP팩 · 체력 +30');}else{const type=selectedWeapons[d.slot];if(!type||type==='pistol')return false;syncAmmo();const before=slotAmmo[d.slot];slotAmmo[d.slot]=Math.min(weapons[type].ammo,before+ammoPickupAmounts[type]);if(slotAmmo[d.slot]===before)return false;if(equippedSlot===d.slot+1)ammo=slotAmmo[d.slot];if(salvageMode&&sortie)sortie.ammoRecovered[type]=(sortie.ammoRecovered[type]||0)+slotAmmo[d.slot]-before;supplyFeedback(d,slotAmmo[d.slot]-before);notify(`${d.slot+(salvageMode?1:2)}번 ${weapons[type].name} · 탄약 +${slotAmmo[d.slot]-before}`);}updateSlotHUD();updateCombatRing();return true;}
