const soundFiles=['ammo-pickup','melee-impact','headshot-clang','laserSmall_000','laserSmall_001','laserSmall_002','laserLarge_000','laserLarge_001','laserLarge_002','explosionCrunch_000','explosionCrunch_001','lowFrequency_explosion_000','forceField_000','doorOpen_000','computerNoise_000','firearms/player-ar','firearms/body-hit','firearms/headshot-ding','firearms/melee-hit','firearms/missile-launch','firearms/player-shotgun','firearms/player-minigun','firearms/player-sniper','firearms/minigun-stop','firearms/enemy-sniper','firearms/enemy-infantry','firearms/rifle','firearms/automatic','firearms/shotgun','firearms/sniper','firearms/rifle_alt','firearms/automatic_alt','firearms/shotgun_alt','firearms/sniper_alt'];
function loadSounds(){if(soundLoading)return soundLoading;soundLoading=Promise.all(soundFiles.map(async name=>{try{const path=name==='firearms/body-hit'?'firearms/body-hit.mp3':name==='firearms/headshot-ding'?'firearms/headshot-cut-339824.mp3':name==='firearms/player-shotgun'?'firearms/player-shotgun-spas12.mp3':(['headshot-clang','melee-impact','ammo-pickup'].includes(name)?name+'.wav':(name.startsWith('firearms/')?name:'kenney/'+name)+'.ogg');const response=await fetch(new URL('audio/'+path,document.baseURI),{cache:'no-cache'});if(!response.ok)throw new Error(response.status);const buffer=await audio.decodeAudioData(await response.arrayBuffer());soundBuffers.set(name,buffer);}catch(error){console.warn('Sound unavailable',name,error);}}));return soundLoading;}
function updateAudioListener(){if(!audio)return;const l=audio.listener,forward=new THREE.Vector3(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch));if(l.positionX){l.positionX.value=player.pos.x;l.positionY.value=player.pos.y;l.positionZ.value=player.pos.z;l.forwardX.value=forward.x;l.forwardY.value=forward.y;l.forwardZ.value=forward.z;l.upX.value=0;l.upY.value=1;l.upZ.value=0;}else{l.setPosition(player.pos.x,player.pos.y,player.pos.z);l.setOrientation(forward.x,forward.y,forward.z,0,1,0);}}
function playSound(name,volume=.2,rate=1,pos=null,priority=false){if(!audio)return;const buffer=soundBuffers.get(name);if(!buffer)return;if(!priority&&activeSoundVoices.size>=32)return;if(activeSoundVoices.size>=48){const oldest=[...activeSoundVoices].find(v=>!v.priority)||activeSoundVoices.values().next().value;oldest.source.stop();oldest.finish();}updateAudioListener();const source=audio.createBufferSource(),gain=audio.createGain();source.buffer=buffer;source.playbackRate.value=rate;gain.gain.value=volume;let panner=null,filter=null;if(pos){panner=audio.createPanner();panner.panningModel='HRTF';panner.distanceModel='inverse';panner.refDistance=4;panner.maxDistance=100;panner.rolloffFactor=1.25;panner.setPosition(pos.x,pos.y,pos.z);filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=18000/(1+pos.distanceTo(player.pos)/18);source.connect(filter);filter.connect(panner);panner.connect(gain);}else source.connect(gain);gain.connect(audio.destination);const voice={source,priority,finish:null};voice.finish=()=>{if(!activeSoundVoices.delete(voice))return;soundVoices=activeSoundVoices.size;source.disconnect();filter?.disconnect();panner?.disconnect();gain.disconnect();};activeSoundVoices.add(voice);soundVoices=activeSoundVoices.size;source.onended=voice.finish;source.start();}

