function spawnRoadGroup(distance,count,returning=false){
 for(let i=0;i<count;i++){
  // Keep encounters spread along the road, but shuffle positions within each sector.
  const sector=Math.floor(distance/Math.max(1,sortieWorld.route.length/selectedMission.blocks)),type=['trooper','scoutDrone','spider','assassin'][(sector+i)%4];let placed=null;
  for(let attempt=0;attempt<160;attempt++){
   const candidate=sortieWorld.route.sample(THREE.MathUtils.clamp(distance+(Math.random()-.5)*18,4,sortieWorld.route.length-8),(Math.random()-.5)*Math.min(sortieWorld.route.width*.72,24));
   if(platforms.some(q=>Math.abs(candidate.x-q.x)<q.w/2+1&&Math.abs(candidate.z-q.z)<q.d/2+1))continue;
   if(enemies.some(e=>Math.hypot(candidate.x-e.group.position.x,candidate.z-e.group.position.z)<3.5))continue;
   placed=candidate;break;
  }
  if(!placed)continue;
  spawn(false,type);const e=enemies.at(-1);e.group.position.set(placed.x,type==='scoutDrone'?7:0,placed.z);e.bossAnchor.copy(e.group.position);e.hp=e.max=(type==='scoutDrone'?40:type==='assassin'?75:type==='spider'?24:55)*(sortie.mission?.difficulty||1);e.speed*=returning?1.08:1;
  e.awareness={state:'idle',timer:0,delay:2.3+i*.25,signal:false};e.home=e.group.position.clone();e.group.rotation.y=Math.random()*Math.PI*2;
 }
}
function startRoadSortie(){
 if(!sortie||sortie.finished||sortie.bossSpawned)return;wave=1;
 for(let i=0;i<selectedMission.blocks;i++)spawnRoadGroup(sortieWorld.route.length*(i+.5)/selectedMission.blocks,selectedMission.enemyCount);
 spawn(true,'blade');const e=enemies.at(-1),end=sortieWorld.route.end;e.group.position.set(end.x,0,end.z+3);e.bossAnchor.copy(e.group.position);e.hp=e.max=900*selectedMission.difficulty;e.awareness={state:'idle',timer:0,delay:2.8,signal:false};e.home=e.group.position.clone();sortie.bossSpawned=true;
 notify('원격 접속 완료 · 거리 끝의 수호 개체와 발전 코어를 찾으세요');
}
function updateRoadAwareness(e,dt){
 if(!e.awareness||e.awareness.state==='combat')return true;
 const eye=e.group.position.clone().add(new THREE.Vector3(0,e.boss?2.8:e.type==='scoutDrone'?.64:e.type==='spider'?.35:1.7,0)),delta=player.pos.clone().sub(eye),distance=delta.length();let visible=false;
 if(distance<40){ray.set(eye,delta.normalize());ray.far=Math.max(0,distance-.4);visible=!ray.intersectObjects(worldObstacles,false).length;}
 if(SALVAGE.updateAwareness(e,dt,player.pos,visible,enemies)){e.attack=0;e.fireClock=.55;e.seenTime=1;return true;}
 e.wantFire=false;
 e.patrolTime=(e.patrolTime||0)-dt;
 const home=e.home||e.group.position,position=e.group.position;
 if(!e.idlePatrolGoal||e.patrolTime<=0||Math.hypot(position.x-e.idlePatrolGoal.x,position.z-e.idlePatrolGoal.z)<.6){
  e.patrolTime=4+Math.random()*4;e.idlePatrolGoal=null;
  for(let i=0;i<12;i++){
   const p=sortieWorld.route.sample(THREE.MathUtils.clamp(sortieWorld.route.progress(home)+(Math.random()-.5)*(e.boss?6:16),2,sortieWorld.route.length-2),(Math.random()-.5)*Math.min(sortieWorld.route.width*.5,6));
   if(Math.hypot(p.x-home.x,p.z-home.z)>12||platforms.some(q=>!q.walkable&&q.h>position.y+.3&&Math.abs(p.x-q.x)<q.w/2+.4&&Math.abs(p.z-q.z)<q.d/2+.4))continue;
   e.idlePatrolGoal=p;break;
  }
 }
 let speed=0;
 if(e.idlePatrolGoal){
  const before=position.clone(),heading=new THREE.Vector3(e.idlePatrolGoal.x-position.x,0,e.idlePatrolGoal.z-position.z).normalize(),velocity=heading.multiplyScalar(e.boss?.7:e.type==='scoutDrone'?.65:1.3),start=position.clone().add(new THREE.Vector3(0,1.7,0));
  if(e.type!=='scoutDrone')velocity.y=-23*dt;
  const step=movePlayerWithSlide(start,start.clone().addScaledVector(velocity,dt),velocity,platforms,{boundsX:platforms.bounds?.x||100,boundsZ:platforms.bounds?.z||210});position.copy(step.position).add(new THREE.Vector3(0,-1.7,0));
  speed=Math.hypot(position.x-before.x,position.z-before.z)/Math.max(dt,.001);
  if(speed<.1)e.patrolTime=Math.min(e.patrolTime,.4);
  if(speed>.1){const angle=Math.atan2(velocity.x,velocity.z),turn=Math.atan2(Math.sin(angle-e.group.rotation.y),Math.cos(angle-e.group.rotation.y));e.group.rotation.y+=turn*(1-Math.exp(-dt*5));}
 }
 if(e.type==='scoutDrone'){position.y=THREE.MathUtils.damp(position.y,home.y+Math.sin(time*.8+home.x)*.18,2,dt);animateBoss(e.robot,dt,time,0);}else if(e.boss)animateBoss(e.robot,dt,time,0);else animateRobot(e.robot,dt,{speed,aim:0});
 e.group.updateMatrixWorld(true);return false;
}
function updateRoadSortie(dt){
 if(!sortie||sortie.finished||dead)return;const recoveredHP=Math.min(maxPlayerHP()-player.hp,sortie.stats.regen*dt);player.hp+=recoveredHP;sortie.hpRecovered=(sortie.hpRecovered||0)+recoveredHP;SALVAGE.tickBattery(sortie,dt,Math.hypot(player.vel.x,player.vel.z));sortieWorld.update(time);updateCargoRack();backEquipment.update(dt,{position:player.pos,avatar:playerAvatar,enemies,time});
 if(sortie.battery<=0){beginGameOver();return;}
 const progress=sortieWorld.route.progress(player.pos),remaining=sortieWorld.route.length-progress;
 const nearExit=Math.hypot(player.pos.x-sortieWorld.route.start.x,player.pos.z-sortieWorld.route.start.z)<5,nearCore=sortieWorld.target.visible&&Math.hypot(player.pos.x-sortieWorld.target.position.x,player.pos.z-sortieWorld.target.position.z)<4;
 extractPrompt.hidden=!(nearExit||nearCore);extractPrompt.textContent=nearCore?(sortieWorld.unlocked?'F · 발전 코어 회수':'보상 잠금 · 수호 개체를 먼저 처치하세요'):`F · ${sortie.core?'수집품을 싣고 본거지 복귀':'철수 · 현재 수집품으로 복귀'}`;
 const estimate=progress*.12*sortie.stats.drain;
 if(!sortie.hudNext||time>=sortie.hudNext||time<sortie.hudNext-.2){sortieHUD.innerHTML=`<b>${sortie.core?'귀환 중 / 적재품 보존':'원격 출격 / 발전 코어 수색'}</b><br>배터리 ${sortie.battery.toFixed(1)} / ${sortie.stats.battery}<br>복귀 이동 예상 ${estimate.toFixed(1)} · 대시 ${(6*sortie.stats.dashEfficiency).toFixed(1)} 소모${sortie.stats.shield?'<br>방어막 '+Math.ceil(sortie.shieldHP||0)+' / '+Math.round(sortie.stats.shield):sortie.stats.autoDamage?'<br>자동 사격 팔 · 가동 중':sortie.stats.houndDamage?'<br>로봇 사냥개 · 동행 중':''}<br>회수 모듈 ${sortie.cargo.length}개 · 회수 무기 ${sortie.lootWeapons.length}개 · 장비 ${sortie.lootEquipment.length}개<br>${sortie.core?'핵심 코어 적재 · 복귀까지 '+progress.toFixed(0)+'m':'도로 끝까지 '+remaining.toFixed(0)+'m · 언제든 철수 가능'}${sortie.battery<estimate+8?'<br><strong>배터리 부족 위험 · 복귀를 고려하세요</strong>':''}`;sortie.hudNext=time+.1;}
 $('wave').textContent=sortie.core?'핵심 코어 확보 · 귀환 중':`도로 수색 ${progress.toFixed(0)} / ${sortieWorld.route.length}m · ${sortie.mission?.blocks||0}블록`;
}
function interactRoadSortie(){
 if(!sortie||sortie.finished||countdownTime>0||dead)return;
 if(sortieWorld.unlocked&&sortieWorld.target.visible&&Math.hypot(player.pos.x-sortieWorld.target.position.x,player.pos.z-sortieWorld.target.position.z)<4){
  const reward=SALVAGE.makeCoreWeapon();sortie.lootWeapons.push(reward);supplyFeedback({kind:'weapon',weaponType:reward.type},1,`${weapons[reward.type].name} Lv.${reward.level} 획득`);sortie.core=true;sortie.cargo.push(SALVAGE.makePart('core',`core-${Date.now()}`));sortieWorld.target.visible=false;campaign.state.deployed.core=true;campaign.save();
  for(let distance=45;distance<sortieWorld.route.length-12;distance+=36)spawnRoadGroup(distance,3,true);sortie.returnAmbush=1;
  notify(`코어 보상 · ${weapons[reward.type].name} Lv.${reward.level} 확보 · 귀환해야 보존됩니다`);return;
 }
 if(Math.hypot(player.pos.x-sortieWorld.route.start.x,player.pos.z-sortieWorld.route.start.z)<5){syncAmmo();sortie.ammo=Object.fromEntries(selectedWeapons.map((w,i)=>[w,slotAmmo[i]]));campaign.finish(sortie,true,player.hp,sortie.core?'핵심 코어 회수 후 귀환':'수색 중 조기 철수');returnToBase();}
}
