 makeWeaponImages();
 baseUI=SALVAGE.createBaseUI(campaign,{prepare:openLoadout,weapons:['pistol','rifle',...specialTypes].map(type=>({...weapons[type],type,image:weaponImages[type]||''})),appearance:(robot,stats)=>{SALVAGE.applyFrameVisual(playerAvatar,stats);return SALVAGE.framePreview(stats);}});
 sortieHUD=document.createElement('div');sortieHUD.id='sortieHUD';sortieHUD.hidden=true;document.body.appendChild(sortieHUD);
