 baseBack=document.createElement('button');baseBack.id='baseBack';baseBack.hidden=true;baseBack.textContent='← 본거지로';baseBack.onclick=()=>{baseBack.hidden=true;$('loadoutOverlay').hidden=true;baseUI.show();};document.body.appendChild(baseBack);
 $('loadoutTitle').textContent='로봇에게 들려 보낼 무기 두 개';$('loadoutTitle').nextElementSibling.textContent='창고의 무기 두 개와 탄약을 기체에 싣습니다. 1·2 키로 전환하며, 전손 시 함께 소실됩니다.';
 document.body.classList.add('salvageMode');$('gameOverTitle').textContent='REMOTE UNIT LOST';$('retryGame').textContent='본거지로 돌아가기';$('wave').textContent='출격 준비';document.querySelector('#hud .brand+small').textContent='원격 회수 작전 / OLD CITY 07';$('saveRecord').hidden=true;document.title='LAST SPARK — 원격 회수 작전';$('overlay').style.display='none';baseUI.show();if(import.meta.env.DEV&&new URLSearchParams(location.search).has('returnReportCheck')){campaign.frame().hp=100;const preview=campaign.launch(campaign.frame().loadout,{});preview.core=true;preview.kills=27;preview.time=245;preview.battery=32;preview.energyUsed=104;preview.energyRecovered=36;preview.hpDamage=42;preview.hpRecovered=10;preview.cargo=[SALVAGE.makePart('armor','report-module'),SALVAGE.makePart('core','report-core')];preview.lootWeapons=[SALVAGE.makeWeapon('sniper','report-gun')];preview.lootEquipment=[SALVAGE.makeEquipment('moto','report-helmet',()=>.5)];preview.ammoRecovered={sniper:8};campaign.finish(preview,true,68,'핵심 코어 회수 후 귀환');baseUI.show(campaign.state.lastReport);}
